def load() -> pd.DataFrame:
    import glob, os
    files = glob.glob("data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Fraud and Other data/*.csv")
    # Check which state file the DC metro comes from
    results = []
    for f in sorted(files):
        state = os.path.splitext(os.path.basename(f))[0]
        raw = pd.read_csv(f, header=None, encoding='latin-1')
        # Find data rows: row 1 is header, rows 2+ are data
        if len(raw) > 2:
            for i in range(2, len(raw)):
                val = str(raw.iloc[i, 0]) if pd.notna(raw.iloc[i, 0]) else ''
                if 'Washington' in val or 'District' in val:
                    results.append({'state_file': state, 'row': i, 'metro': val, 'reports': raw.iloc[i, 1]})
    return pd.DataFrame(results)

def load() -> pd.DataFrame:
    import glob
    folder = "data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Fraud and Other data/"
    states_to_check = ['WestVirginia', 'Virginia', 'Maryland', 'DistrictofColumbia', 'NewYork', 'NewJersey']

    results = []
    for state in states_to_check:
        path = folder + state + '.csv'
        try:
            raw = pd.read_csv(path, header=None, encoding='latin-1')
            results.append({'State': state, 'Rows': len(raw), 'Content': str(raw.values.tolist())[:500]})
        except:
            results.append({'State': state, 'Rows': -1, 'Content': 'ERROR'})

    return pd.DataFrame(results)
